<template>
  <div class="page-container audit-page">
    <div class="page-header"><div><h2>{{ userStore.role?.code === 'province' ? '市级进度审核' : '县级进度审核' }}</h2><p>{{ userStore.role?.code === 'province' ? '省级审核市级提交的进度；审核通过后才计入正式累计进度。' : '市级审核县级提交的进度；审核通过后才进入省级审核。' }}</p></div><div class="scope-label">当前范围：{{ userStore.regionName }}</div></div>
    <el-tabs v-model="type" @tab-change="load"><el-tab-pane label="播种进度审核" name="sow" /><el-tab-pane label="收获进度审核" name="harvest" /></el-tabs>
    <div class="panel"><div class="toolbar"><el-radio-group v-model="status" @change="load"><el-radio-button label="pending">待审核</el-radio-button><el-radio-button label="history">已审核</el-radio-button></el-radio-group><span>共 {{ rows.length }} 条</span></div>
      <el-table :data="rows" stripe border><el-table-column prop="id" label="上报单号" min-width="230"/><el-table-column prop="regionName" label="提交区域" width="150"/><el-table-column prop="level" label="提交层级" width="110"><template #default="{row}">{{ row.level === 'county' ? '县级' : row.level === 'city' ? '市级' : row.level }}</template></el-table-column><el-table-column prop="year" label="年度" width="80"/><el-table-column prop="quarter" label="周期" width="110"/><el-table-column label="类型" width="100"><template #default="{row}">{{ row.type === 'sow' ? '播种' : '收获' }}</template></el-table-column><el-table-column prop="reportedAt" label="提交时间" width="130"/><el-table-column label="状态" width="110"><template #default="{row}"><el-tag :type="statusType(row.status)">{{ row.status }}</el-tag></template></el-table-column><el-table-column label="操作" width="120" fixed="right"><template #default="{row}"><el-button link type="primary" @click="openDetail(row)">查看详情</el-button></template></el-table-column><template #empty><el-empty description="暂无进度审核记录"/></template></el-table>
    </div>
    <el-dialog v-model="visible" title="进度上报详情" width="900px" destroy-on-close><template v-if="current"><el-descriptions :column="3" border><el-descriptions-item label="上报单号">{{ current.id }}</el-descriptions-item><el-descriptions-item label="对应计划">{{ current.planId || '—' }}</el-descriptions-item><el-descriptions-item label="提交区域">{{ current.regionName }}</el-descriptions-item><el-descriptions-item label="状态"><el-tag :type="statusType(current.status)">{{ current.status }}</el-tag></el-descriptions-item><el-descriptions-item label="类型">{{ current.type === 'sow' ? '播种' : '收获' }}</el-descriptions-item><el-descriptions-item label="年度/周期">{{ current.year }}年{{ current.quarter }}</el-descriptions-item><el-descriptions-item label="提交时间">{{ current.reportedAt }}</el-descriptions-item><el-descriptions-item label="累计口径">{{ current.status === '审核通过' ? '计入正式累计' : '暂不计入正式累计' }}</el-descriptions-item></el-descriptions><div class="summary-block submitted"><div class="summary-block-title">{{ current.level === 'county' ? '县级' : current.level === 'city' ? '市级' : '本级' }}上报进度（当前审核对象）</div><div class="summary-grid"><span>计划面积：{{ Number(current.submittedSummary?.planArea || 0).toLocaleString() }} 亩</span><span>本次新增：{{ Number(current.submittedSummary?.increment || 0).toLocaleString() }} 亩</span><span>累计进度：{{ Number(current.submittedSummary?.cumulative || 0).toLocaleString() }} 亩</span></div></div><div class="summary-block child"><div class="summary-block-title">{{ current.level === 'county' ? '乡镇' : current.level === 'city' ? '县级' : '下级' }}进度汇总（明细来源）</div><div class="summary-grid"><span>计划面积：{{ Number(current.childSummary?.planArea || 0).toLocaleString() }} 亩</span><span>本次新增：{{ Number(current.childSummary?.increment || 0).toLocaleString() }} 亩</span><span>累计进度：{{ Number(current.childSummary?.cumulative || 0).toLocaleString() }} 亩</span></div></div><div class="detail-title">进度明细</div><el-table :data="current.details || []" border stripe><el-table-column prop="name" label="乡镇/主体"/><el-table-column prop="planArea" label="计划面积（亩）" align="right"/><el-table-column prop="increment" label="本次新增面积（亩）" align="right"/><el-table-column prop="cumulative" label="累计面积（亩）" align="right"/></el-table><div class="detail-title">审核链路</div><el-timeline><el-timeline-item v-for="item in current.timeline || []" :key="item.time + item.action" :timestamp="item.time">{{ item.operator }}：{{ item.action }}</el-timeline-item></el-timeline><el-input v-if="canReview" v-model="comment" type="textarea" :rows="3" placeholder="退回时必须填写审核意见；通过时可选填"/></template><template #footer><el-button @click="visible=false">关闭</el-button><template v-if="canReview"><el-button type="danger" plain @click="review(false)">退回</el-button><el-button type="success" @click="review(true)">通过</el-button></template></template></el-dialog>
  </div>
</template>

<script setup>
import { computed, onMounted, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { useUserStore } from '@/stores/user'
import { fetchProgressReportOrders, auditProgressReport } from '@/api/gpm'
const userStore = useUserStore(); const type = ref('sow'); const status = ref('pending'); const rows = ref([]); const visible = ref(false); const current = ref(null); const comment = ref('')
const statusType = s => ({ 待审核: 'warning', 审核通过: 'success', 已驳回: 'danger' }[s] || 'info'); const canReview = computed(() => current.value?.status === '待审核' && ((current.value.level === 'county' && userStore.role?.code === 'city') || (current.value.level === 'city' && userStore.role?.code === 'province')))
const load = async () => { const all = await fetchProgressReportOrders(userStore.role, { type: type.value, year: 2026, quarter: '第三季度' }); rows.value = all.filter(x => status.value === 'pending' ? x.status === '待审核' : ['审核通过', '已驳回'].includes(x.status)) }
const openDetail = row => { current.value = row; comment.value = ''; visible.value = true }
const review = async approved => { if (!current.value) return; if (!approved && !comment.value.trim()) return ElMessage.warning('退回时必须填写审核意见'); try { await ElMessageBox.confirm(`确认${approved ? '通过' : '退回'}该进度上报吗？`, '审核确认') } catch { return } const result = await auditProgressReport(current.value.id, { approved, opinion: comment.value }, userStore.role); if (!result.success) return ElMessage.error(result.message); ElMessage.success(approved ? '进度审核已通过' : '进度已退回'); visible.value = false; await load() }
onMounted(load)
</script>

<style lang="scss" scoped>
.audit-page{gap:12px}.page-header{display:flex;align-items:center;justify-content:space-between}.page-header h2{margin:0;color:#1f2937}.page-header p{margin:8px 0 0;color:#909399;font-size:13px}.scope-label{color:#606266;font-size:13px}.panel{background:#fff;border:1px solid #e8edf3;border-radius:8px;padding:16px}.toolbar{display:flex;align-items:center;justify-content:space-between;margin-bottom:14px;color:#667085}.detail-title{font-weight:600;color:#243b5a;margin:18px 0 9px}.summary-block{margin-top:14px;padding:12px;border-radius:8px;border:1px solid #e5ebf2}.summary-block.submitted{background:#eef5ff}.summary-block.child{background:#f1fbf6}.summary-block-title{font-weight:600;color:#243b5a;margin-bottom:8px}.summary-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;color:#667085;font-size:12px}.summary-grid span{padding:8px;background:rgba(255,255,255,.7);border-radius:5px}
</style>